@import "tailwindcss";
@plugin "tw-animate-css";   /* CSS-only; supplies the data-state keyframes shadcn v4 emits */
@custom-variant light (&:where([data-theme="light"], [data-theme="light"] *));

/* ════ raw palette — :root is DARK (D1). hex = measured sRGB, all in gamut ════ */
:root {
  color-scheme: dark;

  /* background layers */
  --bg:          oklch(0.155 0.006 250);  /* #0a0c0f  page                       */
  --bg-raised:   oklch(0.198 0.007 250);  /* #131619  cards, topbar, inspector   */
  --bg-sunken:   oklch(0.122 0.006 250);  /* #050608  log pane, code wells       */
  --surface:     oklch(0.245 0.008 250);  /* #1e2124  inputs, chips, row hover   */

  /* lines — two strengths, different jobs */
  --line:        oklch(0.30  0.009 250);  /* #2a2e32  decorative hairline, no contrast req. */
  --line-strong: oklch(0.55  0.012 250);  /* #6c7278  CONTROL border, must clear 3:1        */

  /* ink */
  --ink-1:       oklch(0.97  0.003 250);  /* #f4f5f7  */
  --ink-2:       oklch(0.80  0.006 250);  /* #bbbec1  */
  --ink-3:       oklch(0.655 0.009 250);  /* #8d9196  */

  /* brand — NOT shadcn's --accent (D3). also the focus ring. */
  --brand:       oklch(0.76  0.100 205);  /* #57c3cf  */
  --brand-ink:   oklch(0.155 0.006 250);  /* text on a filled brand surface */

  /* status */
  --ok:          oklch(0.79  0.155 152);  /* #61d688  */
  --warn:        oklch(0.83  0.145 82);   /* #f6bd48  */
  --err:         oklch(0.72  0.165 22);   /* #fb7475  */
  --idle:        oklch(0.66  0.010 250);  /* #8e9398  */
  --busy:        oklch(0.75  0.100 265);  /* #8fadee  */
}

[data-theme="light"] {
  color-scheme: light;
  --bg:          oklch(0.985 0.002 250);  /* #f9fafb */
  --bg-raised:   oklch(1     0     0);    /* #ffffff */
  --bg-sunken:   oklch(0.955 0.004 250);  /* #eef0f3 */
  --surface:     oklch(0.97  0.003 250);  /* #f4f5f7 */
  --line:        oklch(0.90  0.005 250);  /* #dbdee1 */
  --line-strong: oklch(0.62  0.010 250);  /* #82878c */
  --ink-1:       oklch(0.22  0.010 250);  /* #171b1f */
  --ink-2:       oklch(0.42  0.012 250);  /* #484e54 */
  --ink-3:       oklch(0.50  0.014 250);  /* #5d646b */
  --brand:       oklch(0.52  0.110 235);  /* #01729f */
  --brand-ink:   oklch(1     0     0);
  --ok:          oklch(0.50  0.120 152);  /* #1a763f */
  --warn:        oklch(0.52  0.095 70);   /* #8b5e22 */
  --err:         oklch(0.53  0.190 25);   /* #c2272d */
  --idle:        oklch(0.50  0.010 250);  /* #5f6469 */
  --busy:        oklch(0.50  0.150 265);  /* #385db8 */
}

@media (prefers-contrast: more) { :root, [data-theme="light"] { --line: var(--line-strong); } }

/* ════ token → utility. `inline` so the [data-theme] override reaches shadcn (D2) ════ */
@theme inline {
  --color-bg: var(--bg);
  --color-raised: var(--bg-raised);
  --color-sunken: var(--bg-sunken);
  --color-surface: var(--surface);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ink-1: var(--ink-1);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-brand: var(--brand);
  --color-brand-ink: var(--brand-ink);
  --color-ok: var(--ok);
  --color-warn: var(--warn);
  --color-err: var(--err);
  --color-idle: var(--idle);
  --color-busy: var(--busy);

  /* ── shadcn/ui contract. EVERY name its generated components emit. ──
     Nothing here may be undefined: mcphub shipped bg-card / text-muted-foreground
     with no definition (LogViewer.tsx:70,148,160) and they were silent no-ops.
     theme.contract.test.ts asserts each of these resolves. */
  --color-background: var(--bg);
  --color-foreground: var(--ink-1);
  --color-card: var(--bg-raised);
  --color-card-foreground: var(--ink-1);
  --color-popover: var(--bg-raised);
  --color-popover-foreground: var(--ink-1);
  --color-primary: var(--brand);
  --color-primary-foreground: var(--brand-ink);
  --color-secondary: var(--surface);
  --color-secondary-foreground: var(--ink-1);
  --color-muted: var(--surface);
  --color-muted-foreground: var(--ink-3);
  --color-accent: var(--surface);          /* shadcn "accent" = hover surface, NOT brand (D3) */
  --color-accent-foreground: var(--ink-1);
  --color-destructive: var(--err);
  --color-destructive-foreground: var(--bg);
  --color-border: var(--line);
  --color-input: var(--line-strong);
  --color-ring: var(--brand);
}

/* ════ non-swapping theme values ════ */
@theme {
  --font-sans: "Geist", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* dense console scale. base is 13px, not 16. */
  --text-2xs: 0.6875rem; --text-2xs--line-height: 1rem;      /* 11  log ts, table meta   */
  --text-xs:  0.75rem;   --text-xs--line-height: 1.125rem;   /* 12  dense table body     */
  --text-sm:  0.8125rem; --text-sm--line-height: 1.25rem;    /* 13  DEFAULT UI text      */
  --text-base:0.875rem;  --text-base--line-height: 1.375rem; /* 14  prose, descriptions  */
  --text-lg:  1rem;      --text-lg--line-height: 1.5rem;     /* 16  card titles          */
  --text-xl:  1.25rem;   --text-xl--line-height: 1.75rem;    /* 20  page titles          */
  --text-2xl: 1.75rem;   --text-2xl--line-height: 2rem;      /* 28  stat numerals        */

  /* radius — a control plane is square-ish. nothing above 8px. */
  --radius-xs: 2px;   /* chips, dots, inline code */
  --radius-sm: 3px;   /* inputs, buttons, rows    */
  --radius-md: 4px;   /* cards, popovers          */
  --radius-lg: 6px;   /* panels                   */
  --radius-xl: 8px;   /* dialog + inspector ONLY  */

  --spacing: 4px;           /* v4 base: p-2 = 8px. dense grid uses 1.5 / 2 / 3. */
  --spacing-control: 28px;  /* h-control — default control height             */
  --spacing-row: 32px;      /* h-row     — table / list row                   */
  --spacing-bar: 44px;      /* h-bar     — topbar, tab strip                  */

  --ease-quick: cubic-bezier(0.2, 0, 0, 1);
  --duration-instant: 80ms;  /* hover, press, dot state flip        */
  --duration-quick: 140ms;   /* tooltip, popover, dropdown, toast   */
  --duration-panel: 200ms;   /* inspector slide, dialog, sheet      */
}

/* ════ fonts — self-hosted from the pinned `geist` package (D4) ════ */
@font-face {
  font-family: "Geist";
  src: url("geist/dist/fonts/geist-sans/Geist-Variable.woff2") format("woff2-variations");
  font-weight: 100 900; font-style: normal;
  font-display: optional;           /* the ONLY value with zero FOUT *and* zero CLS */
}
@font-face {
  font-family: "Geist Mono";
  src: url("geist/dist/fonts/geist-mono/GeistMono-Variable.woff2") format("woff2-variations");
  font-weight: 100 900; font-style: normal;
  font-display: optional;
}
/* index.html, in <head>, before the module script:
   <link rel="preload" as="font" type="font/woff2" crossorigin
         href="/assets/Geist-Variable-<hash>.woff2">   (vite-plugin emits the hashed href)
   <link rel="preload" as="font" type="font/woff2" crossorigin
         href="/assets/GeistMono-Variable-<hash>.woff2">
   <html data-theme> is absent by default → dark. No boot script (D9). */

@layer base {
  *, *::before, *::after { border-color: var(--color-border); }
  html { -webkit-text-size-adjust: 100%; }
  body {
    background: var(--color-bg);
    color: var(--color-ink-1);
    font-family: var(--font-sans);
    font-size: var(--text-sm);
    font-variant-numeric: tabular-nums;   /* console-wide. every number aligns by default. */
    font-feature-settings: "cv11" 1;      /* Geist: slashed/disambiguated 1 l I 0 O */
    -webkit-font-smoothing: antialiased;
    overscroll-behavior: none;
  }

  /* ONE focus treatment. visible on every layer, both themes.
     brand vs bg measures 9.45:1 dark / 5.17:1 light — clears the 3:1 non-text floor
     with room. outline-offset puts the ring OUTSIDE a brand-filled button, so it
     never disappears into its own background. */
  :focus-visible { outline: 2px solid var(--color-brand); outline-offset: 2px; border-radius: var(--radius-sm); }
  .bg-sunken :focus-visible, .bg-surface :focus-visible, td :focus-visible { outline-offset: 1px; }
  :focus:not(:focus-visible) { outline: none; }
  /* scroll containers must leave 2px so the offset ring is not clipped */
  [data-scroll] { padding-inline: 2px; }

  ::selection { background: color-mix(in oklab, var(--color-brand) 30%, transparent); }
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--color-line); border-radius: 999px; border: 2px solid transparent; background-clip: content-box; }
  ::-webkit-scrollbar-thumb:hover { background-color: var(--color-line-strong); }
  * { scrollbar-width: thin; scrollbar-color: var(--color-line) transparent; }

  /* the only three !important in the codebase. theme.lint.test.ts asserts the count. */
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 1ms !important;
      transition-duration: 1ms !important;
      scroll-behavior: auto !important;
    }
  }
}

@layer components {
  /* THE identifier look. <Id> is the only thing allowed to apply it. */
  .id {
    font-family: var(--font-mono);
    font-variant-numeric: tabular-nums;
    font-variant-ligatures: none;   /* -> is two glyphs in a server name, not an arrow */
    font-size: 0.9375em;            /* Geist Mono runs optically large beside Geist Sans */
    letter-spacing: -0.005em;
  }
  /* dense table. no wrapper component, just a class (D8 reasoning: fewer files). */
  .rows { width: 100%; border-collapse: separate; border-spacing: 0; }
  .rows > thead > tr > th {
    position: sticky; top: 0; z-index: 1;
    height: var(--spacing-control); padding-inline: calc(var(--spacing) * 2);
    background: var(--color-raised); border-bottom: 1px solid var(--color-line);
    font-size: var(--text-2xs); font-weight: 500; letter-spacing: 0.04em;
    text-transform: uppercase; color: var(--color-ink-3); text-align: left;
  }
  .rows > tbody > tr { height: var(--spacing-row); }
  .rows > tbody > tr > td { padding-inline: calc(var(--spacing) * 2); border-bottom: 1px solid var(--color-line); }
  .rows > tbody > tr:hover { background: var(--color-surface); }
  .rows > tbody > tr[data-selected="true"] { background: color-mix(in oklab, var(--color-brand) 12%, transparent); }
  /* status tint background, derived — no extra tokens */
  .tint-ok   { background: color-mix(in oklab, var(--color-ok)   14%, var(--color-raised)); }
  .tint-warn { background: color-mix(in oklab, var(--color-warn) 14%, var(--color-raised)); }
  .tint-err  { background: color-mix(in oklab, var(--color-err)  14%, var(--color-raised)); }
}

import { memo, useCallback, useState } from 'react';
import { Check, Copy } from 'lucide-react';
import { cn } from '@/lib/utils';

const NUM = new Intl.NumberFormat('en-US');
const ANSI = /\[[0-9;]*m/g;          // upstream stderr leaks escape codes
const MAX = 512;                            // cap attacker-controlled upstream strings

export type IdKind =
  | 'tool' | 'server' | 'group' | 'endpoint' | 'uuid' | 'key'
  | 'tokens' | 'bytes' | 'duration' | 'raw';

const COPYABLE = new Set<IdKind>(['endpoint', 'uuid', 'server', 'tool', 'group']);

export interface IdProps {
  kind: IdKind;
  value: string | number | null | undefined;
  /** required for kind='tool' to dim the namespace prefix; no heuristic split */
  server?: string;
  /** namespace separator, server-configured. default '-' */
  sep?: string;
  copy?: boolean;
  truncate?: boolean;
  className?: string;
}

async function write(text: string) {
  try {
    if (window.isSecureContext && navigator.clipboard) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch { /* fall through */ }
  // ponytail: execCommand fallback exists only for LAN installs served over plain
  // http, where navigator.clipboard is undefined. Delete when docs require https.
  const ta = document.createElement('textarea');
  ta.value = text; ta.readOnly = true;
  ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none';
  document.body.appendChild(ta); ta.select();
  const ok = document.execCommand('copy');
  ta.remove();
  return ok;
}

function parts(kind: IdKind, value: string | number, server?: string, sep = '-') {
  switch (kind) {
    case 'tokens':
      return { text: NUM.format(Number(value)), unit: 'tok' };
    case 'bytes':
      return { text: NUM.format(Math.round(Number(value) / 1024)), unit: 'KiB' };
    case 'duration': {
      const ms = Number(value);
      return ms < 1000
        ? { text: NUM.format(Math.round(ms)), unit: 'ms' }
        : { text: (ms / 1000).toFixed(2), unit: 's' };
    }
    case 'key': {
      // never render a key in full. the plaintext is shown once, at creation, elsewhere.
      const s = String(value);
      return { text: s.length > 10 ? `${s.slice(0, 5)}…${s.slice(-4)}` : s };
    }
    case 'uuid': {
      const s = String(value);
      return { text: s.length > 12 ? `${s.slice(0, 8)}…` : s };
    }
    case 'tool': {
      const s = String(value).replace(ANSI, '').slice(0, MAX);
      const p = server ? `${server}${sep}` : null;
      return p && s.startsWith(p)
        ? { prefix: p, text: s.slice(p.length) }
        : { text: s };
    }
    default:
      return { text: String(value).replace(ANSI, '').slice(0, MAX) };
  }
}

export const Id = memo(function Id(
  { kind, value, server, sep = '-', copy, truncate, className }: IdProps,
) {
  const [done, setDone] = useState(false);
  const full = value == null ? '' : String(value);
  const onCopy = useCallback(async () => {
    if (await write(full)) { setDone(true); setTimeout(() => setDone(false), 1200); }
  }, [full]);

  if (full === '') {
    return <span className={cn('id text-ink-3', className)} aria-label="not set">&mdash;</span>;
  }

  const p = parts(kind, value!, server, sep);
  const showCopy = copy ?? COPYABLE.has(kind);

  return (
    <span className={cn('id group/id inline-flex max-w-full items-baseline gap-1', className)}>
      {p.prefix && <span className="shrink-0 text-ink-3">{p.prefix}</span>}
      <span
        className={cn('text-ink-1', truncate && 'truncate')}
        title={truncate || kind === 'uuid' || kind === 'key' ? full : undefined}
      >
        {p.text}
      </span>
      {p.unit && <span className="shrink-0 text-2xs text-ink-3">{p.unit}</span>}
      {showCopy && (
        <button
          type="button"
          onClick={onCopy}
          aria-label={done ? `Copied ${full}` : `Copy ${full}`}
          className={cn(
            'ml-0.5 grid size-6 shrink-0 place-items-center rounded-xs text-ink-3',
            'transition-opacity duration-instant ease-quick',
            'hover:text-ink-1 focus-visible:opacity-100 group-hover/id:opacity-100',
            'opacity-0 max-lg:opacity-100',   // below 1024 there is no hover; always show
          )}
        >
          {done ? <Check className="size-3 text-ok" aria-hidden /> : <Copy className="size-3" aria-hidden />}
        </button>
      )}
    </span>
  );
});

/* USAGE — this is the whole vocabulary:
   <Id kind="server"   value={s.name} />
   <Id kind="tool"     value={t.name} server={t.server} sep={cfg.separator} />
   <Id kind="endpoint" value={`${origin}/mcp/${group}`} truncate />
   <Id kind="uuid"     value={run.id} />
   <Id kind="tokens"   value={cost.exposed} />
   <Id kind="duration" value={call.latencyMs} />
   <Id kind="key"      value={k.prefix} />            // never the full key
*/

const ID_PROP = /^(name|toolName|serverName|groupName|url|endpoint|baseUrl|command|args|
                   id|uuid|keyId|sessionId|requestId|traceId|
                   tokens|tokenCount|inputTokens|outputTokens|bytes|
                   latencyMs|durationMs|elapsedMs)$/x;

export default {
  meta: {
    type: 'problem',
    docs: { description: 'identifiers and counts must render through <Id>' },
    schema: [],
  },
  create(ctx) {
    return {
      JSXExpressionContainer(node) {
        const parent = node.parent;
        // only JSX *children*, not attributes (title=, aria-label= are fine)
        if (parent?.type !== 'JSXElement' && parent?.type !== 'JSXFragment') return;
        const e = node.expression;
        const prop =
          e?.type === 'MemberExpression' && !e.computed ? e.property.name
          : e?.type === 'Identifier' ? e.name
          : null;
        if (!prop || !ID_PROP.test(prop)) return;
        const tag = parent.openingElement?.name;
        if (tag?.type === 'JSXIdentifier' && tag.name === 'Id') return;
        ctx.report({
          node,
          message: `"${prop}" is an identifier — render it as <Id kind="…" value={…} />, not bare JSX.`,
        });
      },
    };
  },
};

/* THE REST OF THE GUARD RAIL, in eslint.config.js — these four rules are what
   prevents mcphub's index.css:470-1385 retrofit layer from ever existing here:

   'no-restricted-syntax': ['error',
     { selector: `JSXAttribute[name.name='className'] Literal[value=/\\bdark:/]`,
       message: 'No dark: variant. Every color is a token that swaps itself (D1). Add a token.' },
     { selector: `JSXAttribute[name.name='className'] Literal[value=/\\b(bg|text|border|ring|fill|stroke|divide|outline|shadow)-(gray|slate|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-\\d{2,3}\\b/`,
       message: 'Tailwind palette colors are banned. Use bg-raised / text-ink-2 / text-err / …' },
     { selector: `JSXAttribute[name.name='style']`,
       message: 'No inline style. Exception: the four CSS custom properties set by AppShell.' },
     { selector: `JSXAttribute[name.name='className'] Literal[value=/\\[#[0-9a-fA-F]{3,8}\\]|\\[(rgb|hsl|oklch)\\(/]`,
       message: 'No literal color values in class names.' },
   ],
   'react/no-danger': 'error',   // <LogLine> and tool descriptions render upstream text

   plus two tests:
     theme.contract.test.ts  — every shadcn contract name resolves non-empty (jsdom + getComputedStyle)
     theme.lint.test.ts      — theme.css contains exactly 3 '!important' and 0 'tailwind.config'

   plus: tailwind.config.js and postcss.config.js DO NOT EXIST in this repo.
   mcphub kept both as dead v3-era files alongside its v4 setup. */

/*  >=1280                                >=768 <1280            <768
 ┌──────────────────────────────────────────────────────────────────────────┐
 │ TOPBAR  h-bar(44)  [MCPR] [env chip] ···· [⌘K] [●health] [◑] [avatar▾]  │
 ├────────┬───────────────────────────────┬─────────────────────────────────┤
 │ RAIL   │  <main id="main">             │  INSPECTOR                      │
 │ 216px  │  scrolls; px-4 py-3           │  clamp(320px,26vw,720px)        │
 │ ⌘B→48  │  min-w-0 overflow-x-hidden    │  DOCKED, non-modal, resizable   │
 │        │                               │  ⌘\ toggles                     │
 ├────────┴───────────────────────────────┴─────────────────────────────────┤
 │ STATUSBAR h-6(24)  14 servers · 212 tools · p95 84ms · ●live · a3f9c1e   │
 └──────────────────────────────────────────────────────────────────────────┘
   <1280 : inspector becomes <Sheet side="right"> (Radix, focus-trapped)
   <1024 : rail collapses to 48px icon rail, labels move to tooltips
   < 768 : rail becomes a <Sheet side="left"> from a topbar hamburger;
           grid-cols becomes [minmax(0,1fr)]; palette goes full-screen;
           tables shed to 3 columns, remainder lives in the inspector —
           NO horizontal page scroll at any width.

 NAV REGISTRY — rail and palette render from this one array (D7):
   OPERATE  Overview /  · Servers /servers · Groups /groups · Tools /tools
   OBSERVE  Activity /activity · Logs /logs · Metrics /metrics
   EXTEND   Marketplace /market
   ADMIN    Users /users · API keys /keys · Settings /settings#<section>
*/
import { Outlet, useSearchParams } from 'react-router';
import { Toaster } from '@/ui/sonner';

export function AppShell() {
  const [params, setParams] = useSearchParams();
  const inspect = params.get('inspect');          // "server:github" | "tool:github-search" | null
  const docked  = useMediaQuery('(min-width: 1280px)');
  const wide    = useMediaQuery('(min-width: 768px)');
  const [railOpen, setRailOpen] = useLocalStorage('rail', true);

  const closeInspector = () => setParams(p => { p.delete('inspect'); return p; }, { replace: true });
  useHotkeys({ onToggleRail: () => setRailOpen(r => !r), onToggleInspector: () =>
    inspect ? closeInspector() : setParams(p => (p.set('inspect', 'last'), p)) });

  return (
    <div
      className="grid h-dvh grid-rows-[var(--spacing-bar)_minmax(0,1fr)_24px] bg-bg text-ink-1"
      style={{
        '--rail-w': !wide ? '0px' : railOpen ? '216px' : '48px',
        '--insp-w': docked && inspect ? 'clamp(320px, 26vw, 720px)' : '0px',
      } as React.CSSProperties}
    >
      <a href="#main"
         className="sr-only focus:not-sr-only focus:absolute focus:z-50 focus:m-2 focus:rounded-sm focus:bg-raised focus:px-3 focus:py-2">
        Skip to content
      </a>

      <Topbar onMenu={() => setRailOpen(true)} compact={!wide} />

      <div className="grid min-h-0 grid-cols-[var(--rail-w)_minmax(0,1fr)_var(--insp-w)]">
        {wide
          ? <NavRail collapsed={!railOpen} />
          : <Sheet open={railOpen} onOpenChange={setRailOpen}>
              <SheetContent side="left" className="w-[248px] p-0"><NavRail collapsed={false} /></SheetContent>
            </Sheet>}

        <main id="main" data-scroll tabIndex={-1}
              className="min-w-0 overflow-y-auto overflow-x-hidden px-4 py-3">
          <Outlet />
        </main>

        {docked && inspect && (
          /* non-modal on purpose: the page behind stays usable and is NOT focus-trapped */
          <aside role="complementary" aria-label="Inspector"
                 className="min-w-0 overflow-y-auto border-l border-line bg-raised" data-scroll>
            <Inspector target={inspect} onClose={closeInspector} />
          </aside>
        )}
      </div>

      <StatusBar />

      {!docked && inspect && (
        <Sheet open onOpenChange={o => !o && closeInspector()}>
          {/* Radix Dialog underneath -> focus trap, aria-modal, Esc, scroll lock, all free */}
          <SheetContent side="right" className="w-full p-0 sm:max-w-[560px]">
            <Inspector target={inspect} onClose={closeInspector} />
          </SheetContent>
        </Sheet>
      )}

      <CommandPalette />
      <ShortcutSheet />                {/* ? */}
      <Toaster position="bottom-right" toastOptions={{ duration: 4000 }} />
    </div>
  );
}

/* INSPECTOR CONTRACT — the pattern that replaces stacked modals:
   target       "<entity>:<id>"  parsed by a switch in Inspector, one case per entity
   header       <Id> of the subject + StatusDot + close (Esc) + breadcrumb when replaced
   body         tabs: Overview | Tools | Config | Activity   (shadcn <Tabs>)
   footer       destructive actions only; each opens <AlertDialog> — the ONE
                sanctioned layer above the inspector, replacing mcphub's
                window.confirm/alert on ActivityPage.
   navigation   inspector -> inspector REPLACES the param, never pushes. There is
                no stack to leak, and browser Back is the undo. */

GLOBAL
  ⌘K / Ctrl K   command palette
  ?             shortcut cheatsheet
  /             focus this page's search input
  Esc           close palette > close inspector > clear filter   (in that order)
  ⌘B            toggle nav rail (216px <-> 48px)
  ⌘\            toggle inspector
  ⌘⇧K           copy the active endpoint URL
  ⌘⇧L           toggle light/dark
  r             refetch the current route's queries

GO-TO CHORDS  (press g, then the letter; 1200ms window, aborts on any other key)
  g o  Overview      g s  Servers      g g  Groups      g t  Tools
  g a  Activity      g l  Logs         g m  Metrics     g k  API keys
  g u  Users         g ,  Settings

LIST / TABLE  (when a row region has focus)
  j / ↓         next row          k / ↑         previous row
  Enter         open in inspector Space          toggle enabled (server/tool)
  x             mark for bulk     ⌘A             mark all visible
  Backspace     unmark all        ⌘Enter         run the bulk action

LOG VIEW
  f             follow/tail on-off       \   filter to the selected server
  1 2 3 4 5     level floor: trace..error   c   clear the view (client-side only)

FORMS / PLAYGROUND
  ⌘Enter        submit / invoke the tool
  ⌘S            save (where a form has an explicit save)

RESERVED — never bound: ⌘W ⌘T ⌘N ⌘R ⌘L ⌘F ⌘P ⌘= ⌘- (browser).

// packages/web/src/shell/use-hotkeys.ts
const EDITABLE = /^(input|textarea|select)$/i;
const GOTO: Record<string, string> = {
  o: '/', s: '/servers', g: '/groups', t: '/tools', a: '/activity',
  l: '/logs', m: '/metrics', k: '/keys', u: '/users', ',': '/settings',
};

export function useHotkeys(h: Handlers) {
  const nav = useNavigate();
  const chord = useRef<number | null>(null);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.isComposing || e.repeat) return;
      const t = e.target as HTMLElement | null;
      const editing = !!t && (EDITABLE.test(t.tagName) || t.isContentEditable);
      const mod = e.metaKey || e.ctrlKey;

      if (mod && e.key.toLowerCase() === 'k' && !e.shiftKey) { e.preventDefault(); return h.openPalette(); }
      if (mod && e.shiftKey && e.key.toLowerCase() === 'k') { e.preventDefault(); return h.copyEndpoint(); }
      if (mod && e.shiftKey && e.key.toLowerCase() === 'l') { e.preventDefault(); return h.toggleTheme(); }
      if (mod && e.key === 'b')  { e.preventDefault(); return h.onToggleRail(); }
      if (mod && e.key === '\\') { e.preventDefault(); return h.onToggleInspector(); }
      if (e.key === 'Escape')    return h.escape();
      if (editing || mod || e.altKey) return;            // everything below is bare-key

      if (chord.current !== null) {
        window.clearTimeout(chord.current); chord.current = null;
        const to = GOTO[e.key];
        if (to) { e.preventDefault(); nav(to); }
        return;
      }
      if (e.key === 'g') { chord.current = window.setTimeout(() => (chord.current = null), 1200); return; }
      if (e.key === '?') { e.preventDefault(); return h.openCheatsheet(); }
      if (e.key === '/') { e.preventDefault(); return h.focusSearch(); }
      if (e.key === 'r') { e.preventDefault(); return h.refetch(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [h, nav]);
}
// ponytail: one global listener, no scoping stack. List-level j/k/x live in the
// list component's own onKeyDown so they follow focus. Add a scope stack only if
// two list regions ever need to be simultaneously focusable.

